import sys, re, tomllib
from urllib.parse import unquote_plus
sys.path.insert(0, "/app/tools")
import replay as R
from pathlib import Path

root = Path("/app")
items = R.timeline(root)
SINCE = R.to_ms("2027-05-03T14:00:05.000Z")
start = [i for i, it in enumerate(items) if it[2] == "started" and it[0] <= SINCE][-1]


def dur(v):
    if isinstance(v, int):
        return v * 1000
    m = re.fullmatch(r"(\d+)(ms|s|m|h)", v)
    return int(m.group(1)) * {"ms": 1, "s": 1000, "m": 60000, "h": 3600000}[m.group(2)]


def loadcfg(n):
    return tomllib.loads((root / "config/history" / (n + ".toml")).read_text())


def locale_of(h, cfg):
    locs = cfg["locales"]; d = cfg["default_locale"]
    rs = []
    for pos, part in enumerate((h or "").split(",")):
        bits = [b.strip() for b in part.split(";")]
        tag = bits[0]
        if not tag:
            continue
        q = 1.0
        for b in bits[1:]:
            if b.startswith("q="):
                try:
                    q = float(b[2:])
                except ValueError:
                    q = 0
        if q > 0:
            rs.append((-q, pos, tag.lower()))
    rs.sort()
    for _, _, r in rs:
        if r == "*":
            return d
        for l in locs:
            if l.lower() == r:
                return l
        for l in locs:
            if l.lower().split("-")[0] == r.split("-")[0]:
                return l
    return d


def key(path, query, lang, cfg):
    m = re.fullmatch(r"/(books|authors)/([1-9][0-9]*)", path)
    if m:
        route, ident = m.groups()
    elif path == "/search":
        route, ident = "search", ""
    else:
        return None
    pairs = []
    for part in query.split("&") if query else []:
        n, _, v = part.partition("=")
        n = unquote_plus(n); v = unquote_plus(v)
        if n in cfg["ignore_params"] or n.startswith("utm_"):
            continue
        if n == "q":
            v = re.sub(r"\s+", " ", v.lower()).strip()
        pairs.append((n, v))
    pairs.sort()
    vary = cfg["routes"][route].get("vary", [])
    loc = locale_of(lang, cfg) if "Accept-Language" in vary else ""
    return route, ident, (tuple(pairs), loc), dur(cfg["routes"][route]["ttl"])


store = None
cfg = None
out = {}
for at, _, kind, f in items[start:]:
    if kind == "started":
        cfg = loadcfg(f["config"]); store = {}
    elif kind == "stopping":
        store = None
    elif kind == "reload":
        cfg = loadcfg(f["config"])
    elif kind == "flush":
        store.clear()
    else:
        path, _, q = f["target"].partition("?")
        if f["method"] == "PURGE":
            m = re.fullmatch(r"/(books|authors)/([1-9][0-9]*)", path)
            if m:
                for k in [k for k in store if k[0] == m.group(1) and k[1] == m.group(2)]:
                    del store[k]
            out[f["id"]] = ("-", f["cache"], f["target"])
            continue
        if f["method"] != "GET":
            out[f["id"]] = ("-", f["cache"], f["target"]); continue
        k = key(path, q, f["lang"], cfg)
        if k is None:
            out[f["id"]] = ("-", f["cache"], f["target"]); continue
        sk = k[:3]
        if sk in store and at < store[sk]:
            r = "hit"
        else:
            r = "miss"; store[sk] = at + k[3]
        out[f["id"]] = (r, f["cache"], f["target"])

if __name__ == "__main__":
    diff = [(i, v) for i, v in out.items() if v[0] != v[1]]
    print(len(out), "diff vs log", len(diff))
    import variants
    names = ["utm_locale_purge_ttl"]
    res = variants.run("/tmp/pkg_all")
    d2 = [i for i, v in res.items() if v[1] != out[i][0] and out[i][0] != "-" ]
    print("all-fixed pkg vs ref differ", len(d2), d2[:10])

